# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span

class RoundLabelTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 11)]
        self.assertEqual(round_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        self.assertEqual(round_labels([Span(0, 65)], 10), ["00:00-01:10 (1h 10m)"])

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 240)]
        self.assertEqual(len(round_labels(spans, 30)), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)
